ALTER POLICY verification_requests_submit ON public.ip_verification_requests WITH CHECK(public.has_role(auth.uid(),'admin') AND declared_authorized AND submission_status='submitted' AND verification_status='MANUAL_REVIEW_REQUIRED' AND administrator_decision IS NULL AND administrator_notes IS NULL AND official_confirmation_url IS NULL AND completed_at IS NULL AND lease_until IS NULL AND processing_error IS NULL AND (listing_id IS NULL OR EXISTS(SELECT 1 FROM public.ip_listings l WHERE l.id=listing_id AND l.owner_id=user_id)));
ALTER POLICY journals_public_read ON public.kipi_journals TO authenticated USING(public.has_role(auth.uid(),'admin'));
ALTER POLICY pages_authenticated_read ON public.kipi_journal_pages USING(public.has_role(auth.uid(),'admin'));
ALTER POLICY records_authenticated_read ON public.kipi_ip_records USING(public.has_role(auth.uid(),'admin'));
ALTER POLICY sync_public_read ON public.kipi_sync_runs TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.claim_ip_verification(p_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator MFA required'; END IF; UPDATE public.ip_verification_requests SET submission_status='processing',lease_until=now()+interval '5 minutes',updated_at=now() WHERE id=p_id AND administrator_decision IS NULL AND (submission_status IN ('submitted','failed') OR (submission_status='processing' AND lease_until<now())); RETURN FOUND; END $$;
CREATE OR REPLACE FUNCTION public.listing_portfolio_totals(p_admin boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public AS $$ BEGIN IF p_admin AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator MFA required'; END IF; RETURN jsonb_build_object('active',(SELECT count(*) FROM public.listing_subscriptions s WHERE (p_admin OR s.owner_id=auth.uid()) AND s.expires_at>now() AND NOT s.admin_hidden AND (EXISTS(SELECT 1 FROM public.ip_listings l WHERE l.id=s.ip_listing_id AND l.status='active' AND l.verification_status='verified') OR EXISTS(SELECT 1 FROM public.service_listings v WHERE v.id=s.service_listing_id AND v.status='approved'))),'upcoming',(SELECT count(*) FROM public.listing_subscriptions s WHERE (p_admin OR s.owner_id=auth.uid()) AND NOT s.admin_hidden AND s.expires_at>now() AND s.expires_at<=now()+interval '14 days'),'suspended',(SELECT count(*) FROM public.listing_subscriptions s WHERE (p_admin OR s.owner_id=auth.uid()) AND (s.expires_at<=now() OR s.admin_hidden)),'verified_live_revenue',(SELECT coalesce(sum(amount),0) FROM public.listing_payments p WHERE (p_admin OR p.owner_id=auth.uid()) AND p.status='succeeded' AND p.environment='live' AND p.applied_at IS NOT NULL),'successful_payments',(SELECT count(*) FROM public.listing_payments p WHERE (p_admin OR p.owner_id=auth.uid()) AND p.status='succeeded' AND p.environment='live'),'failed_payments',(SELECT count(*) FROM public.listing_payments p WHERE (p_admin OR p.owner_id=auth.uid()) AND p.status='failed'),'pending_payments',(SELECT count(*) FROM public.listing_payments p WHERE (p_admin OR p.owner_id=auth.uid()) AND p.status IN ('initiating','pending','unknown'))); END $$;
REVOKE ALL ON FUNCTION public.listing_portfolio_totals(boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.listing_portfolio_totals(boolean) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.process_listing_visibility_notifications() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.listing_subscriptions; days_left integer; event_kind text; event text; inserted uuid; n integer:=0; BEGIN FOR s IN SELECT subscriptions.* FROM public.listing_subscriptions subscriptions WHERE NOT subscriptions.admin_hidden AND subscriptions.expires_at<now()+interval '15 days' AND (EXISTS(SELECT 1 FROM public.ip_listings l WHERE l.id=subscriptions.ip_listing_id AND l.status='active' AND l.verification_status='verified') OR EXISTS(SELECT 1 FROM public.service_listings v WHERE v.id=subscriptions.service_listing_id AND v.status='approved')) AND NOT EXISTS(SELECT 1 FROM public.listing_visibility_events e WHERE e.subscription_id=subscriptions.id AND e.event_key=subscriptions.id::text||':'||subscriptions.expires_at::text||':suspended') ORDER BY CASE WHEN subscriptions.expires_at>now() THEN 0 ELSE 1 END,subscriptions.expires_at LIMIT 500 LOOP days_left:=(s.expires_at AT TIME ZONE 'Africa/Nairobi')::date-(now() AT TIME ZONE 'Africa/Nairobi')::date; event_kind:=CASE WHEN s.expires_at<=now() THEN 'suspended' WHEN s.period_type='introductory' AND days_left IN (14,7,3) THEN 'reminder_'||days_left WHEN s.period_type='paid' AND days_left IN (7,3) THEN 'reminder_'||days_left END; IF event_kind IS NOT NULL THEN event:=s.id::text||':'||s.expires_at::text||':'||event_kind; INSERT INTO public.listing_visibility_events(subscription_id,owner_id,event_key,kind) VALUES(s.id,s.owner_id,event,event_kind) ON CONFLICT(event_key) DO NOTHING RETURNING id INTO inserted; IF inserted IS NOT NULL THEN INSERT INTO public.notifications(user_id,kind,title,body,listing_id) VALUES(s.owner_id,'listing_visibility',CASE WHEN event_kind='suspended' THEN 'Listing visibility suspended' ELSE 'Listing renewal due in '||days_left||' days' END,'Renew this listing for KSh 1,000 / 30 days from your dashboard. Your listing and documents have not been deleted.',s.ip_listing_id); n:=n+1; END IF; END IF; END LOOP; RETURN n; END $$;
CREATE OR REPLACE FUNCTION public.record_listing_payment_failure() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='failed' AND OLD.status IS DISTINCT FROM NEW.status THEN INSERT INTO public.notifications(user_id,kind,title,body,listing_id) SELECT NEW.owner_id,'listing_payment','M-Pesa renewal failed','The payment did not complete. No renewal was applied; your listing, documents and payment history remain saved.',s.ip_listing_id FROM public.listing_subscriptions s WHERE s.id=NEW.subscription_id; INSERT INTO public.audit_logs(actor_id,action,entity_type,entity_id,metadata) VALUES(NEW.owner_id,'listing.payment_failed','listing_payment',NEW.id,jsonb_build_object('environment',NEW.environment,'amount',NEW.amount)); END IF; RETURN NEW; END $$;
CREATE TRIGGER listing_payment_failure_notice AFTER UPDATE OF status ON public.listing_payments FOR EACH ROW EXECUTE FUNCTION public.record_listing_payment_failure();